// Demo mode: six realistic test emails (one per category, plus a
// prompt-injection attempt) so the workflow runs without Gmail.
// Generated from test-data/sample-emails.json.

const SAMPLE_EMAILS = [
  {
    "message_id": "demo-001",
    "from": "Dana Whitfield <dana.whitfield@bigclient.example>",
    "subject": "Dashboards not loading - board meeting at 3pm",
    "body": "Hi team,\n\nSince about 9:40 this morning none of our Northwind dashboards load. Every chart shows \"Data source timeout\" and the whole finance team is blocked. We have our quarterly board meeting at 3pm today and the revenue deck is built on these dashboards.\n\nCan someone look at this right away and tell me if there is a workaround in the meantime?\n\nThanks,\nDana Whitfield\nHead of Finance Operations, BigClient",
    "timestamp": "2026-09-28T09:52:00Z"
  },
  {
    "message_id": "demo-002",
    "from": "Marco Rossi <marco.rossi@freshcart.example>",
    "subject": "Pricing for 40 seats + SSO?",
    "body": "Hello,\n\nI'm Head of Data at FreshCart (online grocery, ~300 employees). We're evaluating analytics platforms to replace our current BI tool before our contract renews on 31 October.\n\nCould you send pricing for roughly 40 seats, and confirm whether SSO (Okta) and a Snowflake connector are included in the Business plan? If it looks like a fit, I'd like to book a demo for my team next week.\n\nBest regards,\nMarco Rossi",
    "timestamp": "2026-09-28T10:15:00Z"
  },
  {
    "message_id": "demo-003",
    "from": "Priya Nair <priya.nair@lumenlabs.example>",
    "subject": "CSV export cuts off at 10,000 rows",
    "body": "Hi support,\n\nWhen I export the \"Monthly Orders\" report to CSV, the file always stops at exactly 10,000 rows even though the report has about 14,500. Excel export works fine, so I can use that for now, but our ETL job expects CSV.\n\nIs this a limit on our plan or a bug? Workspace ID: lumen-analytics-02.\n\nThanks!\nPriya",
    "timestamp": "2026-09-28T11:03:00Z"
  },
  {
    "message_id": "demo-004",
